<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import EmpirePage from '../components/EmpirePage.vue'
import { PALACE_PLAN, PALACE_ZONES, type EmpireState, type PalaceZone } from '../core/empire'
import type { PageKey } from '../core/navigation'
const props = defineProps<{ state: EmpireState }>()
const emit = defineEmits<{ notice: [string]; navigate: [PageKey] }>()
const selectedId = ref('taihe'), zone = ref<PalaceZone | 'all'>('all')
const selected = computed(() => props.state.halls.find(h => h.id === selectedId.value)!)
const selectedPlan = computed(() => PALACE_PLAN.find(h => h.id === selectedId.value)!)
const halls = computed(() => PALACE_PLAN.map(plan => ({ ...plan, ...props.state.halls.find(h => h.id === plan.id)! })))
const visibleHalls = computed(() => halls.value.filter(h => zone.value === 'all' || h.zone === zone.value))
const name = ref(''), purpose = ref(''), error = ref('')
function hallLines(value: string) { const chars = Array.from(value); return chars.length > 6 ? [chars.slice(0, 6).join(''), chars.slice(6).join('')] : [value] }
watch(selected, hall => { name.value = hall.name; purpose.value = hall.purpose; error.value = '' }, { immediate: true })
function select(id: string) { selectedId.value = id }
function filter(value: PalaceZone | 'all') { zone.value = value; if (value !== 'all' && selectedPlan.value.zone !== value) selectedId.value = PALACE_PLAN.find(h => h.zone === value)!.id }
function submit() {
  const nextName = name.value.trim(), nextPurpose = purpose.value.trim()
  if (!nextName || Array.from(nextName).length > 12 || Array.from(nextPurpose).length > 160) { error.value = '殿名不能为空，最多 12 字；用途最多 160 字。'; return }
  selected.value.name = nextName; selected.value.purpose = nextPurpose; error.value = ''; emit('notice', '宫殿图已更新')
}
</script>
<template>
  <EmpirePage title="宫殿地图" eyebrow="THE IMPERIAL PALACE" description="中轴贯南北，宫阙列东西。点击一座宫殿，查看与题写殿名。">
    <template #actions><span class="map-summary">{{ halls.length }} 处宫阙 · 北上南下</span></template>
    <div class="management-toolbar"><div class="management-tabs" aria-label="宫殿分区"><button :aria-pressed="zone === 'all'" @click="filter('all')">全宫</button><button v-for="(label, key) in PALACE_ZONES" :key="key" :aria-pressed="zone === key" @click="filter(key)">{{ label }}</button></div><span class="management-summary">外朝议政 · 内廷起居 · 宫务收储 · 苑囿游赏</span></div>
    <div class="palace-layout"><section class="management-card map-panel" aria-label="宫殿平面图"><svg class="palace-map" viewBox="0 0 1000 900" role="group" aria-label="宫城建筑位置图"><defs><pattern id="map-grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" class="map-grid-line" fill="none" /></pattern></defs><rect x="30" y="25" width="940" height="845" rx="2" class="map-ground" /><rect x="30" y="25" width="940" height="845" fill="url(#map-grid)" /><rect x="60" y="45" width="880" height="810" rx="2" class="palace-wall" /><rect x="80" y="125" width="840" height="255" class="inner-court" /><path d="M500 120V840M100 380H900M100 770H900" class="palace-axis" /><path d="M145 245H855M145 360H855M145 490H855M145 625H855M145 755H855" class="palace-path" /><text x="92" y="100" class="map-direction">北 ↑</text><text x="920" y="842" text-anchor="end" class="map-direction">南 · 入朝</text><text x="895" y="360" text-anchor="end" class="zone-label">内廷</text><text x="895" y="760" text-anchor="end" class="zone-label">外朝</text><g aria-hidden="true" class="garden-trees"><circle v-for="x in [330,370,630,670]" :key="x" :cx="x" cy="85" r="18" /></g><g v-for="hall in halls" :key="hall.id" class="map-hall" :class="{ selected: hall.id === selectedId, dimmed: zone !== 'all' && hall.zone !== zone, garden: hall.zone === 'garden' }" role="button" tabindex="0" :aria-label="`${hall.name}，${PALACE_ZONES[hall.zone]}`" :aria-pressed="hall.id === selectedId" :transform="`translate(${hall.x}, ${hall.y})`" @click="select(hall.id)" @keydown.enter.prevent="select(hall.id)" @keydown.space.prevent="select(hall.id)"><rect x="-80" y="-34" width="160" height="75" rx="2" class="hall-courtyard" /><path d="M-77-21-57-40H57L77-21Z" class="hall-roof" /><path d="M-70-21H70M-52-32H52" class="roof-lines" /><rect x="-62" y="-15" width="124" height="42" class="hall-body" /><path d="M-70 30H70M-60 35H60" class="hall-steps" /><text text-anchor="middle" :font-size="hallLines(hall.name).length > 1 ? 12 : 16"><tspan v-for="(line, i) in hallLines(hall.name)" :key="i" x="0" :y="hallLines(hall.name).length > 1 ? i * 16 : 11">{{ line }}</tspan></text></g></svg><p class="map-footnote">宫城示意 · 沿中轴自午门入朝，至御花园游赏</p></section><aside class="hall-sidebar"><section class="management-card hall-details" :aria-label="`${selected.name}详情`"><span class="management-badge">{{ PALACE_ZONES[selectedPlan.zone] }}</span><h2>{{ selected.name }}</h2><p>{{ selected.purpose || '用途待定' }}</p><form class="management-form" @submit.prevent="submit"><label>宫殿名称<input v-model="name" class="text-input" maxlength="12" required /></label><label>宫殿用途<textarea v-model="purpose" class="text-input" maxlength="160" /></label><p v-if="error" class="overflow-warning" role="alert">{{ error }}</p><button class="button management-secondary" type="submit">保存殿名与用途</button></form><button v-if="['treasury','royal-vault'].includes(selected.id)" class="text-button hall-link" @click="emit('navigate', 'treasury')">查看国库与皇室宝库 ↗</button><button v-if="selected.id === 'wuying' || selected.id === 'wenyuan'" class="text-button hall-link" @click="emit('navigate', 'officials')">查看文武百官 ↗</button><button v-if="selected.id === 'qinzheng' || selected.id === 'qianqing'" class="text-button hall-link" @click="emit('navigate', 'memorials')">移驾御前批阅奏折 ↗</button><button v-if="selectedPlan.zone === 'residence'" class="text-button hall-link" @click="emit('navigate', 'emperor')">移驾赛博皇帝 ↗</button></section><section class="management-card hall-directory"><h3>宫阙名录</h3><button v-for="hall in visibleHalls" :key="hall.id" :aria-pressed="selectedId === hall.id" @click="select(hall.id)"><span>{{ hall.name }}</span><small>{{ PALACE_ZONES[hall.zone] }}</small></button></section></aside></div>
  </EmpirePage>
</template>
<style scoped>
.map-summary { color: var(--muted); font-size: 12px; }.palace-layout { display: grid; grid-template-columns: minmax(0, 1fr) 280px; gap: 24px; align-items: start; }.map-panel { padding: 15px; }.palace-map { display: block; width: 100%; height: auto; }.map-ground { fill: color-mix(in srgb, var(--accent) 3%, var(--panel)); }.map-grid-line { stroke: var(--line); stroke-width: .5; }.palace-wall { fill: none; stroke: var(--accent); stroke-width: 3; opacity: .5; }.inner-court { fill: color-mix(in srgb, var(--accent) 3%, transparent); stroke: var(--line); }.palace-axis { fill: none; stroke: var(--accent); opacity: .2; stroke-width: 12; }.palace-path { fill: none; stroke: var(--accent); opacity: .15; stroke-width: 3; }.map-direction, .zone-label { fill: var(--muted); font: 13px var(--font-serif); letter-spacing: 2px; }.garden-trees { fill: color-mix(in srgb, var(--muted) 10%, transparent); stroke: var(--muted); stroke-width: 1; opacity: .6; }.map-hall { cursor: pointer; outline: none; transition: opacity .2s; }.map-hall.dimmed { opacity: .25; }.hall-courtyard { fill: var(--panel); stroke: var(--line); }.hall-roof { fill: color-mix(in srgb, var(--accent) 16%, var(--panel)); stroke: var(--accent); stroke-width: 1.2; }.roof-lines, .hall-steps { fill: none; stroke: var(--accent); opacity: .5; }.hall-body { fill: var(--panel); stroke: var(--accent); opacity: .85; }.map-hall text { fill: var(--text); font-family: var(--font-serif); letter-spacing: 2px; pointer-events: none; }.map-hall.selected .hall-courtyard, .map-hall:focus-visible .hall-courtyard { stroke: var(--accent); stroke-width: 3; }.map-hall.selected .hall-roof, .map-hall:hover .hall-roof { fill: color-mix(in srgb, var(--accent) 40%, var(--panel)); }.map-footnote { color: var(--muted); font-size: 10px; text-align: center; margin: 8px 0 10px; letter-spacing: 1px; }.hall-sidebar { display: grid; gap: 20px; }.hall-details h2 { font: 26px var(--font-serif); margin: 20px 0 12px; letter-spacing: 4px; overflow-wrap: anywhere; }.hall-details > p { color: var(--muted); font-size: 12px; line-height: 1.9; margin-bottom: 24px; overflow-wrap: anywhere; }.hall-link { margin-top: 19px; }.hall-directory h3 { font: 16px var(--font-serif); margin: 0 0 16px; letter-spacing: 3px; }.hall-directory button { display: flex; align-items: center; justify-content: space-between; gap: 10px; width: 100%; padding: 11px 0; border: 0; border-bottom: 1px solid var(--line); color: var(--text); background: none; font: 12px var(--font-serif); text-align: left; }.hall-directory button[aria-pressed='true'] { color: var(--accent); }.hall-directory small { color: var(--muted); font: 9px var(--font-sans); white-space: nowrap; }
@media (max-width: 900px) { .palace-layout { grid-template-columns: 1fr; }.hall-sidebar { grid-template-columns: 1fr 1fr; align-items: start; } }
@media (max-width: 600px) { .hall-sidebar { grid-template-columns: 1fr; }.map-panel { padding: 4px; }.map-footnote { font-size: 9px; }.management-summary { line-height: 1.8; } }
</style>
